SELECT COUNT(*) AS nb_grands_projets, 
       COUNT(*) FILTER (WHERE type = 'gare_futur') AS nb_gares_gpe,
       COUNT(*) FILTER (WHERE type LIKE 'canal%') AS nb_canaux,
       COUNT(*) FILTER (WHERE importance = 'nationale') AS nb_nationales
FROM public.dim_grands_projets;